package com.bookstore.security; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.util.*;
@Service public class JwtService {private final SecretKey key; private final long exp; public JwtService(@Value("${app.jwt.secret}")String secret,@Value("${app.jwt.expiration-ms}")long e){key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));exp=e;} public String generate(String u){return Jwts.builder().subject(u).issuedAt(new Date()).expiration(new Date(System.currentTimeMillis()+exp)).signWith(key).compact();} public String username(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().getSubject();}}
